async function openJourney(existing=null,src=null,members=null){src=src||await source();members=members||await window.LuviaMemoryAlbums.listMembers();const u=me(),{destination}=tripInfo(),freshExisting=existing?.id?await window.LuviaMemoryJourneys.get(existing.id):existing;const dayKey=m=>m.dayKey||m.day_key||String(m.capturedAt||m.createdAt||'').slice(0,10)||'undatiert',days=src.days.map((key,i)=>{const media=src.media.filter(m=>dayKey(m)===key),clusters=src.clusters.filter(c=>c.mediaIds.some(id=>media.some(m=>String(m.id)===String(id)))),saved=freshExisting?.chapters?.find(c=>c.day_key===key);return{key,media,clusters,title:saved?.title||`Unser ${fmt(key)||`Reisetag ${i+1}`}`,story:saved?.metadata?.richSummary||saved?.summary||'',cover:saved?.cover_media_id||media[0]?.id,weight:saved?.metadata?.importance||2}}),mine=freshExisting?.contributions?.find(c=>String(c.user_id)===String(u.id)),p=JOURNEY_PROMPTS.find(x=>x[0]===mine?.prompt_key)||choosePrompt(JOURNEY_PROMPTS),weights={...(freshExisting?.metadata?.weights?.media||{})};src.media.forEach(m=>weights[String(m.id)]??=m.favorite?3:2);const state={scene:0,id:freshExisting?.id||null,title:freshExisting?.title||'',story:freshExisting?.metadata?.richStory||freshExisting?.description||'',cover:freshExisting?.cover_media_id||src.media[0]?.id,answer:mine?.metadata?.richText||mine?.answer_text||'',reaction:mine?.reaction||'',promptKey:p[0],prompt:mine?.prompt_text||p[1],days,weights,status:freshExisting?.status||'draft'};const {root,stage,close}=overlay('journey'),total=7;
 const save=async(status=state.status)=>{const items=[];state.days.forEach((d,di)=>{d.clusters.forEach((c,i)=>items.push({chapterPosition:di,position:i,itemType:'cluster',clusterId:c.id,dayKey:d.key,metadata:{title:c.title,importance:d.weight||2}}));const used=new Set(d.clusters.flatMap(c=>c.mediaIds.map(String)));d.media.filter(m=>!used.has(String(m.id))).forEach((m,i)=>items.push({chapterPosition:di,position:d.clusters.length+i,itemType:'media',mediaId:m.id,dayKey:d.key,metadata:{importance:state.weights[String(m.id)]||2}}))});const r=await window.LuviaMemoryJourneys.save({id:state.id,title:state.title||`Unsere Reise nach ${destination}`,description:plain(state.story),coverMediaId:state.cover,status,chapters:state.days.map(d=>({title:d.title,dayKey:d.key,summary:plain(d.story),coverMediaId:d.cover,metadata:{richSummary:d.story,importance:d.weight||2,photoCount:d.media.length,clusterCount:d.clusters.length}})),items,metadata:{richStory:state.story,weights:{media:state.weights},participants:members.map(m=>m.id),experience:'memory-journey-cinema-v1'}});state.id=r.id;state.status=status;return r};
 const paint=async()=>{let body='';if(state.scene===0){const hero=src.media.find(m=>String(m.id)===String(state.cover))||src.media[0];body=`<div class="mw3-journey-open"><div class="mw3-bg" data-jhero></div><div class="mw3-journey-map"><svg viewBox="0 0 500 300" preserveAspectRatio="none"><path d="M30 240 C120 40 220 270 320 80 S450 70 475 35"/><circle cx="30" cy="240" r="8"/><circle cx="475" cy="35" r="8"/></svg></div><div class="mw3-journey-copy"><small>MEMORY JOURNEY · ${state.days.length} TAGE</small><h1>${esc(destination)}<br><em>noch einmal.</em></h1><p>${src.media.length} Bilder · ${src.clusters.length} Memory Moments · ${members.length} Reisende</p><p class="sub">Nicht als Album. Als gemeinsame Reise zurück.</p><button data-start>${icon('play')} Reise starten</button></div></div>`;stage.innerHTML=chrome(0,total,'Memory Journey','Die ganze Reise · gemeinsam')+`<div class="mw3-scene journey">${body}</div>`;stage.querySelector('[data-close]').onclick=close;setImg(stage.querySelector('[data-jhero]'),hero);stage.querySelector('[data-start]').onclick=()=>{state.scene=1;paint()};animateStage(stage);return}
 if(state.scene===1){body=`<div class="mw3-screen-title"><small>SZENE 02 · DIE TAGE</small><h2>Jeder Tag bekommt<br><em>seinen eigenen Rhythmus.</em></h2><p>Die KI darf aus Fotos, EXIF, GPS, Orten und vorhandener Bildanalyse Vorschläge machen. Ihr entscheidet, was wirklich stimmt.</p></div><div class="mw3-day-reel">${state.days.map((d,i)=>`<article data-day="${i}" class="w${d.weight}"><div class="mw3-day-image" data-day-img="${i}"></div><section><small>${esc(fmt(d.key))} · ${d.media.length} Bilder</small><div class="mw3-day-title-row"><input data-day-title="${i}" value="${esc(d.title)}"><button data-ai-day="${i}">${icon('spark')}</button></div>${richEditor('day-'+i,d.story)}${importance(d.weight,'day-'+i)}</section></article>`).join('')}</div>`;stage.innerHTML=sceneTemplate({kind:'journey',scene:1,total,title:'Memory Journey',sub:'Eure Tage',body,next:'Durch eure Momente reisen'});stage.querySelector('[data-close]').onclick=close;for(let i=0;i<state.days.length;i++){const d=state.days[i];setImg(stage.querySelector(`[data-day-img="${i}"]`),d.media.find(m=>String(m.id)===String(d.cover))||d.media[0]);stage.querySelector(`[data-day-title="${i}"]`).oninput=e=>d.title=e.target.value;bindEditor(stage,'day-'+i,v=>d.story=v);stage.querySelector(`[data-ai-day="${i}"]`).onclick=async e=>{e.currentTarget.disabled=true;const r=await ai('memory.day-story',{instruction:'Erzeuge für diesen Reisetag einen natürlichen, persönlichen Titel und einen kurzen atmosphärischen Text. Nutze Bildinhalt nur, wenn er aus Vision/Fotoanalyse oder dem Bild selbst belegbar ist. Nutze GPS, EXIF, Orte und Zeiten. Nichts erfinden.',date:d.key,destination,media:await visualEvidence(d.media),places:uniq(d.media.map(m=>m.metadata?.resolvedLocation?.name)),participants:members.map(m=>m.displayName)},{});d.title=r.title||d.title;d.story=r.text||r.story||d.story;paint()};stage.querySelectorAll(`[data-weight-name^="day-"] [data-weight]`).forEach(b=>b.onclick=()=>{const i=Number(b.closest('[data-weight-name]').dataset.weightName.split('-')[1]);state.days[i].weight=Number(b.dataset.weight);paint()})}bindNav();animateStage(stage);return}
 if(state.scene===2){body=`<div class="mw3-screen-title"><small>SZENE 03 · DURCH DIE REISE</small><h2>Memory Moments sind<br><em>kleine Türen im großen Film.</em></h2><p>Öffnet sie, blättert durch die Bilder und markiert, welche Szenen später im Highlight-Film laut sein dürfen.</p></div><div class="mw3-route">${state.days.map((d,di)=>`<section><header><b>${String(di+1).padStart(2,'0')}</b><div><small>${esc(fmt(d.key))}</small><h3>${esc(d.title)}</h3></div></header><div class="mw3-route-moments">${d.clusters.map((c,ci)=>`<button data-cluster="${c.id}"><div data-cl-img="${di}-${ci}"></div><span><b>${esc(c.title||'Memory Moment')}</b><small>${c.mediaIds.length} Bilder · eintauchen</small></span></button>`).join('')}${d.media.length?`<div class="mw3-route-loose"><b>+ ${d.media.length} Bilder</b><span>Auch die kleinen Zwischenräume bleiben Teil der Reise.</span></div>`:''}</div></section>`).join('')}</div>`;stage.innerHTML=sceneTemplate({kind:'journey',scene:2,total,title:'Memory Journey',sub:'Lebendige Momente',body,next:'Alle Stimmen hören'});stage.querySelector('[data-close]').onclick=close;for(let di=0;di<state.days.length;di++)for(let ci=0;ci<state.days[di].clusters.length;ci++){const c=state.days[di].clusters[ci],m=(await window.LuviaMemoryAlbums.mediaByIds([c.mediaIds[0]]))[0];setImg(stage.querySelector(`[data-cl-img="${di}-${ci}"]`),m,c.title)}stage.querySelectorAll('[data-cluster]').forEach(b=>b.onclick=async()=>previewCluster(src.clusters.find(c=>String(c.id)===String(b.dataset.cluster)),members));bindNav();animateStage(stage);return}
 if(state.scene===3){const fresh=state.id?await window.LuviaMemoryJourneys.get(state.id):freshExisting,contrib=fresh?.contributions||[];body=`<div class="mw3-split journey"><section><small>SZENE 04 · VIELE BLICKE</small><h2>Die Reise gehört<br><em>allen, die dabei waren.</em></h2><p>${esc(state.prompt)}</p>${richEditor('journey-voice',state.answer)}<div class="mw3-reaction-title">Und welches Gefühl hängt daran?</div>${reactionCloud(state.reaction)}${importance(mine?.metadata?.importance||2,'jvoice')}<button class="mw3-question" data-new-question>↻ Andere Frage</button></section><aside>${peopleRail(members,contrib)}<div class="mw3-live-voices">${contrib.map((c,i)=>`<blockquote style="--i:${i}"><b>${esc(c.reaction||'💛')}</b><span>${esc(memberName(c.user_id,members))}</span><p>${esc(c.answer_text||'')}</p></blockquote>`).join('')||'<div class="mw3-await">Noch still. Sobald jemand etwas beiträgt, wird die Reise hier mehrstimmig.</div>'}</div></aside></div>`;stage.innerHTML=sceneTemplate({kind:'journey',scene:3,total,title:'Memory Journey',sub:'Gemeinsam erinnern',body,next:'Was soll im Film bleiben?'});stage.querySelector('[data-close]').onclick=close;bindEditor(stage,'journey-voice',v=>state.answer=v);stage.querySelectorAll('[data-reaction]').forEach(b=>b.onclick=()=>{state.reaction=b.dataset.reaction;paint()});stage.querySelector('[data-new-question]').onclick=()=>{const p=choosePrompt(JOURNEY_PROMPTS,state.promptKey);state.promptKey=p[0];state.prompt=p[1];paint()};stage.querySelectorAll('[data-weight]').forEach(b=>b.onclick=()=>state.voiceWeight=Number(b.dataset.weight));bindNav(async()=>{await save('draft');if(plain(state.answer)||state.reaction)await window.LuviaMemoryJourneys.saveContribution(state.id,{promptKey:state.promptKey,promptText:state.prompt,answerText:plain(state.answer),reaction:state.reaction,metadata:{richText:state.answer,importance:state.voiceWeight||2}})});animateStage(stage);return}
 if(state.scene===4){body=`<div class="mw3-director"><div><small>SZENE 05 · HIGHLIGHT-CUT</small><h2>Eine ganze Reise ist zu viel<br>für fünfzehn Sekunden.</h2><p>Darum bestimmt ihr, was Hintergrund, wichtig oder Herzstück ist. Luvia nutzt diese Gewichtung für Wrapped, Story, Reel und den späteren Reisefilm.</p></div><div class="mw3-director-stats"><b>${src.media.filter(m=>state.weights[String(m.id)]===3).length}</b><span>Herzstücke</span><b>${state.days.filter(d=>d.weight===3).length}</b><span>Schlüsseltage</span></div></div><div class="mw3-weight-grid journey">${src.media.slice(0,30).map((m,i)=>`<article class="w${state.weights[String(m.id)]||2}"><div data-jwimg="${i}"></div><footer><div>${[1,2,3].map(n=>`<button data-photo-weight="${n}" data-id="${m.id}" class="${Number(state.weights[String(m.id)])===n?'on':''}">${icon('star')}</button>`).join('')}</div><button data-cover="${m.id}">${String(state.cover)===String(m.id)?'Cover':'Cover wählen'}</button></footer></article>`).join('')}</div>`;stage.innerHTML=sceneTemplate({kind:'journey',scene:4,total,title:'Memory Journey',sub:'Highlight-Cut',body,next:'Eure Reise erzählen'});stage.querySelector('[data-close]').onclick=close;src.media.slice(0,30).forEach((m,i)=>setImg(stage.querySelector(`[data-jwimg="${i}"]`),m));stage.querySelectorAll('[data-photo-weight]').forEach(b=>b.onclick=()=>{state.weights[String(b.dataset.id)]=Number(b.dataset.photoWeight);paint()});stage.querySelectorAll('[data-cover]').forEach(b=>b.onclick=()=>{state.cover=b.dataset.cover;paint()});bindNav();animateStage(stage);return}
 if(state.scene===5){const fresh=state.id?await window.LuviaMemoryJourneys.get(state.id):freshExisting,voices=fresh?.contributions||[];if(!state.story)state.story=`<p>${state.days.map(d=>plain(d.story)||d.title).filter(Boolean).join(' ')}</p>`;const ideas=localJourneyTitles(destination);body=`<div class="mw3-journey-lab"><section class="titles"><small>SZENE 06 · REISE-ATELIER</small><h2>Wie heißt eure Geschichte?</h2><div class="mw3-title-cloud compact">${ideas.slice(0,8).map((t,i)=>`<button style="--r:${(i%5)-2}deg" data-title="${esc(t)}">${esc(t)}</button>`).join('')}</div><button class="mw3-ai-wide" data-ai-title>${icon('spark')} Aus der ganzen Reise neue Titel erfinden</button><input class="mw3-title-input" data-title-input value="${esc(state.title||`Unsere Reise nach ${destination}`)}"></section><section class="story"><h3>Und wie soll sie klingen?</h3>${richEditor('journey-story',state.story)}${toneStudio()}</section><aside>${peopleRail(members,voices)}<div class="mw3-context-pills">${uniq(src.media.map(m=>m.metadata?.resolvedLocation?.name)).slice(0,8).map(x=>`<span>📍 ${esc(x)}</span>`).join('')}<span>🍽️ Essen & Genuss</span><span>🌦️ Wetter & Stimmung</span><span>👥 ${members.length} Reisende</span><span>📸 ${src.media.length} Bilder</span></div></aside></div>`;stage.innerHTML=sceneTemplate({kind:'journey',scene:5,total,title:'Memory Journey',sub:'Reise-Atelier',body,next:'Wrapped & Film öffnen'});stage.querySelector('[data-close]').onclick=close;bindEditor(stage,'journey-story',v=>state.story=v);stage.querySelectorAll('[data-title]').forEach(b=>b.onclick=()=>{state.title=b.dataset.title;stage.querySelector('[data-title-input]').value=state.title});stage.querySelector('[data-title-input]').oninput=e=>state.title=e.target.value;stage.querySelector('[data-ai-title]').onclick=async e=>{e.currentTarget.disabled=true;const r=await ai('memory.journey-title',{instruction:'Erzeuge 16 kurze, persönliche deutsche Reisetitel. Natürlich, frech, warm, witzig, romantisch, nostalgisch. Kein Marketing, keine KI-Floskeln. Nutze nur echte Reiseinformationen.',destination,days:state.days.map(d=>({date:d.key,title:d.title,story:plain(d.story)})),voices:voices.map(v=>v.answer_text),media:await visualEvidence(src.media)},{});const arr=uniq(r.titles||r.titleSuggestions||localJourneyTitles(destination));stage.querySelector('.mw3-title-cloud').innerHTML=arr.slice(0,12).map(t=>`<button data-title="${esc(t)}">${esc(t)}</button>`).join('');stage.querySelectorAll('[data-title]').forEach(b=>b.onclick=()=>{state.title=b.dataset.title;stage.querySelector('[data-title-input]').value=state.title});e.currentTarget.disabled=false};stage.querySelectorAll('[data-tone]').forEach(b=>b.onclick=async()=>{b.disabled=true;state.story=await rewrite(state.story,b.dataset.tone,{destination,days:state.days.map(d=>({title:d.title,story:plain(d.story)})),voices:voices.map(v=>v.answer_text),media:await visualEvidence(src.media)});paint()});bindNav(async()=>save('draft'));animateStage(stage);return}
 const fresh=await window.LuviaMemoryJourneys.get(state.id),voices=(fresh?.contributions||[]).map(v=>({...v,name:memberName(v.user_id,members)})),highlights=src.media.slice().sort((a,b)=>(state.weights[String(b.id)]||2)-(state.weights[String(a.id)]||2));body=`<div class="mw3-wrapped-stage"><div class="mw3-wrapped-cards"><article class="active"><span>01</span><small>LUVIA WRAPPED</small><h2>${esc(state.title||`Unsere Reise nach ${destination}`)}</h2><p>${state.days.length} Tage · ${src.media.length} Bilder · ${members.length} Reisende</p></article><article><span>02</span><small>EUER GEFÜHL</small><h2>${esc(plain(state.story).slice(0,180)||'Eine Reise, die geblieben ist.')}</h2></article><article><span>03</span><small>EURE STIMMEN</small><div class="mw3-wrapped-voices">${voices.map(v=>`<blockquote><b>${esc(v.reaction||'💛')}</b><p>${esc(v.answer_text||'')}</p><span>${esc(v.name)}</span></blockquote>`).join('')||'<blockquote><p>Die erste Stimme wartet auf die anderen.</p></blockquote>'}</div></article><article><span>04</span><small>EURE TAGE</small><div class="mw3-wrapped-days">${state.days.map((d,i)=>`<div><b>${String(i+1).padStart(2,'0')}</b><span>${esc(d.title)}</span></div>`).join('')}</div></article><article><span>05</span><small>DAS BLEIBT</small><h2>Nicht nur, wo ihr wart.<br><em>Was es euch bedeutet hat.</em></h2></article></div><div class="mw3-prem-controls"><button data-prev>←</button><button data-play>${icon('play')} Wrapped abspielen</button><button data-next-slide>→</button></div>${exportStudio({})}</div>`;stage.innerHTML=sceneTemplate({kind:'journey',scene:6,total,title:'Memory Journey',sub:'Luvia Wrapped',body,back:'Zurück ins Atelier',next:'Gemeinsam bewahren'});stage.querySelector('[data-close]').onclick=close;let wi=0,timer=null;const show=n=>{const cards=[...stage.querySelectorAll('.mw3-wrapped-cards>article')];wi=(n+cards.length)%cards.length;cards.forEach((c,i)=>c.classList.toggle('active',i===wi))};stage.querySelector('[data-prev]').onclick=()=>show(wi-1);stage.querySelector('[data-next-slide]').onclick=()=>show(wi+1);stage.querySelector('[data-play]').onclick=e=>{if(timer){clearInterval(timer);timer=null;e.currentTarget.innerHTML=`${icon('play')} Wrapped abspielen`}else{timer=setInterval(()=>show(wi+1),2600);e.currentTarget.innerHTML=`${icon('pause')} Pause`}};bindExports(stage,{title:state.title,story:state.story,media:highlights,voices,weights:state.weights});bindNav(null,async()=>{if(timer)clearInterval(timer);await save('published');toast('Eure Memory Journey ist gemeinsam bewahrt.');close();renderHome()});animateStage(stage)};
 function bindNav(beforeNext=null,customNext=null){const back=stage.querySelector('[data-back]'),next=stage.querySelector('.mw3-nav [data-next]');if(back)back.onclick=()=>{state.scene=Math.max(0,state.scene-1);paint()};if(next)next.onclick=async()=>{if(customNext)return customNext();if(beforeNext)await beforeNext();state.scene=Math.min(total-1,state.scene+1);paint()}}
 paint()}
async function previewCluster(cluster,members){if(!cluster)return;const media=await window.LuviaMemoryAlbums.mediaByIds(cluster.mediaIds),{stage,close}=overlay('preview');stage.innerHTML=`${chrome(0,1,'Memory Moment','Vorschau')}<div class="mw3-preview"><div class="mw3-preview-film">${media.map((m,i)=>`<div data-pimg="${i}"></div>`).join('')}</div><div><small>MEMORY MOMENT</small><h2>${esc(cluster.title||'Euer Moment')}</h2><p>${media.length} Bilder · Tippt euch noch einmal hinein.</p><button data-open>${icon('play')} Als Memory Moment öffnen</button></div></div>`;stage.querySelector('[data-close]').onclick=close;media.forEach((m,i)=>setImg(stage.querySelector(`[data-pimg="${i}"]`),m));stage.querySelector('[data-open]').onclick=()=>{close();openMoment(cluster,members)}}
